    // FAQ Questions and Answers
    "what-documents-needed": "விவசாய கடன்களுக்கு என்ன ஆவணங்கள் தேவை?",
    "what-documents-needed-answer": "பொதுவாக உங்களுக்கு ஆதார் அட்டை, பான் அட்டை, நில ஆவணங்கள், வருமான சான்று, வங்கி அறிக்கைகள் மற்றும் பாஸ்போர்ட் அளவு புகைப்படங்கள் தேவை. குறிப்பிட்ட தேவைகள் வங்கியின் அடிப்படையில் மாறுபடலாம்.",
    "how-long-approval": "அனுமதி செயல்முறை எவ்வளவு நேரம் எடுக்கும்?",
    "how-long-approval-answer": "அனுமதி நேரம் வங்கி மற்றும் கடன் வகையைப் பொறுத்து 5-21 நாட்கள் வரை மாறுபடும். தனியார் வங்கிகள் பொதுவாக அரசு வங்கிகளை விட வேகமாக செயலாக்குகின்றன.",
    "what-interest-rates": "தற்போதைய வட்டி விகிதங்கள் என்ன?",
    "what-interest-rates-answer": "வட்டி விகிதங்கள் வங்கி, கடன் வகை மற்றும் உங்கள் கடன் சுயவிவரத்தைப் பொறுத்து 7.1% முதல் 15% வரை இருக்கும். அரசு வங்கிகள் பொதுவாக குறைந்த விகிதங்களை வழங்குகின்றன.",
    "minimum-loan-amount": "குறைந்தபட்ச கடன் தொகை என்ன?",
    "minimum-loan-amount-answer": "குறைந்தபட்ச கடன் தொகைகள் வங்கி மற்றும் கடன் வகையைப் பொறுத்து ₹25,000 முதல் ₹1,50,000 வரை மாறுபடும்.",
    "subsidies-available-answer": "ஆம், பல்வேறு அரசு திட்டங்கள் விவசாய கடன்களுக்கு மானியங்களை வழங்குகின்றன, குறிப்பாக உபகரண வாங்குதல் மற்றும் நில மேம்பாட்டிற்கு।",

