    // FAQ Questions and Answers
    "what-documents-needed": "వ్యవసాయ రుణాలకు ఏ పత్రాలు అవసరం?",
    "what-documents-needed-answer": "సాధారణంగా మీకు ఆధార్ కార్డ్, పాన్ కార్డ్, భూమి పత్రాలు, ఆదాయ రుజువు, బ్యాంక్ స్టేట్‌మెంట్లు మరియు పాస్‌పోర్ట్ సైజ్ ఫోటోలు అవసరం. నిర్దిష్ట అవసరాలు బ్యాంక్ ప్రకారం మారవచ్చు.",
    "how-long-approval": "ఆమోద ప్రక్రియ ఎంత సమయం పడుతుంది?",
    "how-long-approval-answer": "ఆమోద సమయం బ్యాంక్ మరియు రుణ రకాన్ని బట్టి 5-21 రోజుల వరకు మారుతుంది. ప్రైవేట్ బ్యాంకులు సాధారణంగా ప్రభుత్వ బ్యాంకుల కంటే వేగంగా ప్రాసెస్ చేస్తాయి.",
    "what-interest-rates": "ప్రస్తుత వడ్డీ రేట్లు ఏమిటి?",
    "what-interest-rates-answer": "వడ్డీ రేట్లు బ్యాంక్, రుణ రకం మరియు మీ క్రెడిట్ ప్రొఫైల్ ఆధారంగా 7.1% నుండి 15% వరకు ఉంటాయి. ప్రభుత్వ బ్యాంకులు సాధారణంగా తక్కువ రేట్లను అందిస్తాయి.",
    "minimum-loan-amount": "కనీస రుణ మొత్తం ఎంత?",
    "minimum-loan-amount-answer": "కనీస రుణ మొత్తాలు బ్యాంక్ మరియు రుణ రకాన్ని బట్టి ₹25,000 నుండి ₹1,50,000 వరకు మారుతాయి.",
    "subsidies-available-answer": "అవును, వివిధ ప్రభుత్వ పథకాలు వ్యవసాయ రుణాలకు సబ్సిడీలను అందిస్తాయి, ముఖ్యంగా పరికరాల కొనుగోలు మరియు భూమి అభివృద్ధికి।",

